    smallest, largest = PLANS[plan.strip().lower()]
    if size >= largest:
        return largest
    unit = 64 * KIB
    return min(largest, max(smallest, -(-size // unit) * unit))


def _part_checksum(part: bytes) -> str:
    return "sha256=" + base64.b64encode(hashlib.sha256(part).digest()).decode()


def _file_checksum(parts: list[bytes]) -> str:
    outer = hashlib.sha256()
    for part in parts:
        outer.update(hashlib.sha256(part).digest())
    return base64.urlsafe_b64encode(outer.digest()).decode().rstrip("=") + f"-{len(parts)}"


def _send_part(transport: Transport, upload_id: str, n: int, part: bytes) -> str:
    r = _call(transport, "PUT", f"{BASE}/uploads/{upload_id}/parts/{n}", part, {"Part-Checksum": _part_checksum(part)})
    return r["etag"]


def upload_file(
    transport: Transport,
    name: str,
    data: bytes,
    plan: str,
    session: Session | None = None,
    record: Callable[[Session], None] | None = None,
) -> StoredFile:
    """Uploads `data` as the file `name` and returns the stored file.

    `plan` is the account's plan as our account records hold it. `session` is a session saved from
    an earlier call for the same name and data that did not finish, or None; it is resumed when that
    is allowed. `record`, when given, is called with every session this call starts, before its first
    part is sent. Raises ApiError when the API answers with an error that ends the upload.
    """
    replaced = False
    current = session
    if current is not None and not current.expires_at > transport.now() + RESUME_MARGIN:
        current = None
    while True:
        etags: dict[int, str] = {}
        try:
            if current is None:
                chunk = _chunk_size(plan, len(data))
                s = _call(transport, "POST", f"{BASE}/uploads", {"name": name, "size": len(data), "chunk_size": chunk})
                current = Session(s["upload_id"], s["chunk_size"], s["expires_at"])
                if record is not None:
                    record(current)
                resumed = False
            else:
                resumed = session is current
            size = current.chunk_size
            parts = [data[o : o + size] for o in range(0, len(data), size)]
            uid = current.upload_id
            held: dict[int, dict[str, Any]] = {}
            if resumed:
                try:
                    listing = _call(transport, "GET", f"{BASE}/uploads/{uid}/parts")
                except ApiError as e:
                    if (e.status, e.code) in ((410, "upload_expired"), (404, "not_found")) and not replaced:
                        replaced = True
                        current = None
                        continue
                    raise
                held = {p["part"]: p for p in listing["parts"]}
            for n, part in enumerate(parts, 1):
                h = held.get(n)
                if h is not None and h["size"] == len(part) and h["checksum"] == _part_checksum(part):
                    etags[n] = h["etag"]
                else:
                    etags[n] = _send_part(transport, uid, n, part)
            commit = {"parts": [{"part": n, "etag": etags[n]} for n in range(1, len(parts) + 1)], "checksum": _file_checksum(parts)}
            path = f"{BASE}/uploads/{uid}/commit"
            try:
                return _stored(_call(transport, "POST", path, commit))
            except ApiError as e:
                if (e.status, e.code) != (409, "parts_missing"):
                    raise
                missing = sorted(e.missing)
            for n in missing:
                etags[n] = _send_part(transport, uid, n, parts[n - 1])
            commit["parts"] = [{"part": n, "etag": etags[n]} for n in range(1, len(parts) + 1)]
            return _stored(_call(transport, "POST", path, commit))
        except ApiError as e:
            if (e.status, e.code) == (410, "upload_expired") and not replaced:
                replaced = True
                current = None
                continue
            raise
